#!/usr/bin/env node
// Fail the build when src/data/page-dates.json has rotted behind git — i.e.
// when a page was committed after its recorded sitemap <lastmod>.
//
//   npm run dates:check
//
// WHY THIS EXISTS. page-dates.json is generated by `npm run seo:dates` from git
// history and COMMITTED, because Cloudflare Pages builds from a shallow clone
// and cannot run `git log` per file (see build-page-dates.mjs). That design is
// right, but it made the refresh a manual step with nothing to remind anyone —
// so it silently rotted: measured 2026-08-09, ALL 40 static routes carried a
// lastmod older than their last commit (32 of them stamped 2026-07-29 against
// a real git date of 2026-08-06). The sitemap was telling crawlers the site
// had not changed in eleven days while a whole structured-data pass shipped.
//
// A stale lastmod is worse than none: it actively tells a crawler not to
// re-fetch a page that did change.
//
// DEGRADES GRACEFULLY, and that is the whole trick. On Cloudflare's shallow
// clone the git data this compares against is not available, so the check
// SKIPS with a notice rather than failing a deploy over a question it cannot
// answer. It fails only where the answer is knowable: a developer's machine,
// or CI with fetch-depth: 0. Otherwise this guard would itself become the
// thing people learn to ignore.
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { ROOT, STATIC_ROUTES } from "./lib/config.mjs";

const EDITORIAL_DATES = JSON.parse(fs.readFileSync(path.join(ROOT, "src/data/guide-editorial-dates.json"), "utf8"));

const DATES_PATH = path.join(ROOT, "src", "data", "page-dates.json");

const git = (args) => {
	try {
		return execFileSync("git", args, { cwd: ROOT, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
	} catch {
		return null;
	}
};

// --- can we answer the question at all? -------------------------------------
if (!fs.existsSync(path.join(ROOT, ".git"))) {
	console.log("[dates:check] SKIPPED — no .git (deploy checkout). Dates are verified locally and on CI.");
	process.exit(0);
}
if (git(["rev-parse", "--is-shallow-repository"]) === "true") {
	console.log("[dates:check] SKIPPED — shallow clone; per-file history unavailable. Run locally or with fetch-depth: 0.");
	process.exit(0);
}

let recorded;
try {
	recorded = JSON.parse(fs.readFileSync(DATES_PATH, "utf8"));
} catch {
	console.error(`[dates:check] FAILED — cannot read ${path.relative(ROOT, DATES_PATH)}. Run: npm run seo:dates`);
	process.exit(1);
}

const routeToFile = (route) =>
	route === "/" ? "index.html" : `${route.replace(/^\/|\/$/g, "")}/index.html`;

const stale = [];
const untracked = [];
let checked = 0;

for (const route of STATIC_ROUTES) {
	const file = routeToFile(route);
	if (!fs.existsSync(path.join(ROOT, file))) continue;
	const committed = EDITORIAL_DATES[route] || git(["log", "-1", "--format=%cs", "--", file]);
	// No commit yet = a brand-new page. build-page-dates.mjs keeps the previous
	// value in that case by design, so it is not drift.
	if (!committed || !/^\d{4}-\d{2}-\d{2}$/.test(committed)) continue;
	checked++;
	const have = recorded[route];
	if (!have) { untracked.push(`${route} — no entry in page-dates.json`); continue; }
	if (committed > have) stale.push({ route, have, committed });
}

if (untracked.length) {
	console.error("[dates:check] routes missing from page-dates.json:");
	for (const u of untracked) console.error("  - " + u);
}

if (stale.length) {
	console.error(
		`[dates:check] FAILED — ${stale.length} of ${checked} route(s) have a sitemap ` +
		`<lastmod> older than their last commit:`,
	);
	for (const s of stale.slice(0, 15)) {
		console.error(`  - ${s.route.padEnd(48)} lastmod=${s.have}  git=${s.committed}`);
	}
	if (stale.length > 15) console.error(`  … and ${stale.length - 15} more`);
	console.error(
		`\n  Fix: npm run seo:dates  (then commit src/data/page-dates.json).\n` +
		`  Run it as the LAST step before committing a change to page copy —\n` +
		`  it reads committed history, so running it first records the old date.`,
	);
	process.exit(1);
}

if (untracked.length) process.exit(1);

console.log(`[dates:check] OK — sitemap lastmod matches git for all ${checked} static route(s).`);
